package com.mutemagictrees;

import net.runelite.api.AmbientSoundEffect;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.AmbientSoundEffectCreated;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.util.Iterator;

@PluginDescriptor(
	name = "Mute Magic Trees",
	description = "Mutes Magic Tree ambient sound effects while allowing all other ambient sounds to continue playing",
	tags = {"sound", "magic tree", "ambient"}
)
public class MuteMagicTreesPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;

	// The ambient sound of ObjectID.MAGICTREE. There is no gameval constant for sound effects.
	private static final int MAGIC_TREE_AMBIENT_SOUND_ID = 3134;

	@Override
	protected void startUp()
	{
		// reload the scene to remove magic tree ambient sounds
		reloadScene();
	}

	@Override
	protected void shutDown()
	{
		// reload the scene to reapply magic tree ambient sounds
		reloadScene();
	}

	@Subscribe
	public void onGameStateChanged(final GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			filterMagicTreeAmbientSound();
		}
	}

	@Subscribe
	public void onAmbientSoundEffectCreated(final AmbientSoundEffectCreated ambientSoundEffectCreated)
	{
		// a magic tree growing back after being chopped adds its sound again after the scene has loaded
		if (ambientSoundEffectCreated.getAmbientSoundEffect().getSoundEffectId() == MAGIC_TREE_AMBIENT_SOUND_ID)
		{
			filterMagicTreeAmbientSound();
		}
	}

	private void reloadScene()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	private void filterMagicTreeAmbientSound()
	{
		final Iterator<AmbientSoundEffect> iterator = client.getAmbientSoundEffects().iterator();

		while (iterator.hasNext())
		{
			if (iterator.next().getSoundEffectId() == MAGIC_TREE_AMBIENT_SOUND_ID)
			{
				iterator.remove();
			}
		}
	}
}

package com.mutemagictrees;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MuteMagicTreesPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MuteMagicTreesPlugin.class);
		RuneLite.main(args);
	}
}
